// One named frame of unchanged original kernels, preserving the numeric short conversion.
#define main original_cli_main
#include "../../flame-cuda/main.cu"
#undef main
#include <vector>
#include <iomanip>
#include <cstdint>
#include <filesystem>
template<class T>void save(std::string f,const std::vector<T>&v){std::ofstream s(f,std::ios::binary);s.write((char*)v.data(),v.size()*sizeof(T));}
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){std::cerr<<cudaGetErrorString(e)<<"\n";exit(3);}}while(0)
int main(int argc,char**argv){std::string out=argv[1];std::filesystem::create_directories(out);ConstMemParams params{};float weights[20]={1,.5f,.6f};float sum=0;int count=0;for(int j=0;j<20;j++){sum+=weights[j];params.variation_parameters[j][0].factor=1;params.pre_transform_params[j][0]=params.pre_transform_params[j][4]=params.post_transform_params[j][0]=params.post_transform_params[j][4]=1;}
 params.pre_transform_params[0][0]=1.4f;params.pre_transform_params[0][1]=.6f;params.pre_transform_params[1][2]=.4f;params.pre_transform_params[2][0]=.3f;params.pre_transform_params[2][2]=-1;params.pre_transform_params[2][5]=-1;params.function_colors[0]=1;params.function_colors[2]=.4f;params.enable_sierpinski=1;params.variation_parameters[2][0].idx=9;params.variation_parameters[0][0].idx=13;params.variation_parameters[1][0].idx=5;params.variation_parameters[1][1].idx=7;params.variation_parameters[1][1].factor=-.3f;
 for(int j=0;j<20;j++){params.thread_function_mapping[j]=int((weights[j]/sum)*NUM_THREADS);count+=params.thread_function_mapping[j];}params.thread_function_mapping[0]+=NUM_THREADS-count;for(int j=1;j<20;j++)params.thread_function_mapping[j]+=params.thread_function_mapping[j-1];
 std::vector<float2>start(NUM_THREADS);std::vector<float>randoms(NUM_THREADS);std::vector<unsigned short>perms(NUM_THREADS*80);for(int i=0;i<NUM_THREADS;i++){start[i]=make_float2((float(i)/NUM_THREADS-.5f)*2,(radical_inverse(i,2)-.5f)*2);randoms[i]=float((i*97+13)%1024)/1024;}for(int p=0;p<80;p++)for(int i=0;i<NUM_THREADS;i++)perms[p*NUM_THREADS+i]=(i*(2*p+1)+p*127)&(NUM_THREADS-1);
 save(out+"/start.bin",start);save(out+"/random_used_prefix.bin",randoms);save(out+"/perms_used_prefix.bin",perms);std::vector<ConstMemParams>pv{params};save(out+"/params.bin",pv);
 float2*ds;float*dr;unsigned short*dp;short2*dxy;short*dc;float3*dv;CK(cudaMalloc(&ds,start.size()*sizeof(float2)));CK(cudaMalloc(&dr,randoms.size()*4));CK(cudaMalloc(&dp,perms.size()*2));CK(cudaMalloc(&dxy,NUM_THREADS*sizeof(short2)));CK(cudaMalloc(&dc,NUM_THREADS*2));CK(cudaMalloc(&dv,NUM_THREADS*NUM_POINTS_PER_THREAD*sizeof(float3)));CK(cudaMemcpy(ds,start.data(),start.size()*sizeof(float2),cudaMemcpyHostToDevice));CK(cudaMemcpy(dr,randoms.data(),randoms.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dp,perms.data(),perms.size()*2,cudaMemcpyHostToDevice));dim3 g(NUM_THREADS/32),b(32);
 kernel_initialize<<<g,b>>>(dxy,dc,dp,0,ds,dr,params);CK(cudaDeviceSynchronize());std::vector<short2>xy(NUM_THREADS);std::vector<short>colors(NUM_THREADS);CK(cudaMemcpy(xy.data(),dxy,xy.size()*sizeof(short2),cudaMemcpyDeviceToHost));CK(cudaMemcpy(colors.data(),dc,colors.size()*2,cudaMemcpyDeviceToHost));save(out+"/initialized_short_points.bin",xy);save(out+"/initialized_short_colors.bin",colors);int bad=0;for(auto c:colors)bad+=c!=0;std::cout<<"original_initialized_nonzero_colors "<<bad<<" of "<<NUM_THREADS<<"; intendedhalfcolorsforfunctions0/1/2=.75/.25/.45\n";
 for(int i=0;i<15;i++){kernel_iterate<<<g,b>>>(dxy,dc,dp,i+1,dr,params);CK(cudaDeviceSynchronize());}kernel_generate_points<<<g,b>>>(dv,dxy,dc,dp,16,dr,params);CK(cudaDeviceSynchronize());CK(cudaMemcpy(xy.data(),dxy,xy.size()*sizeof(short2),cudaMemcpyDeviceToHost));CK(cudaMemcpy(colors.data(),dc,colors.size()*2,cudaMemcpyDeviceToHost));std::vector<float3>vertices(NUM_THREADS*NUM_POINTS_PER_THREAD);CK(cudaMemcpy(vertices.data(),dv,vertices.size()*sizeof(float3),cudaMemcpyDeviceToHost));save(out+"/final_short_points.bin",xy);save(out+"/final_short_colors.bin",colors);save(out+"/vertices.bin",vertices);int nonzero=0,nonfinite=0;for(auto c:colors)nonzero+=c!=0;for(auto v:vertices)nonfinite+=!std::isfinite(v.x)||!std::isfinite(v.y)||!std::isfinite(v.z);std::cout<<"original_final_nonzero_colors "<<nonzero<<"; vertices "<<vertices.size()<<"; nonfinite "<<nonfinite<<"\n";return bad||nonzero?4:0;}
